CREATE TABLE IF NOT EXISTS app_user (id VARCHAR(36) PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(200) NOT NULL, nickname VARCHAR(80) NOT NULL, role VARCHAR(16) NOT NULL);
CREATE TABLE IF NOT EXISTS campsite (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, city VARCHAR(80) NOT NULL, terrain VARCHAR(40) NOT NULL, facilities VARCHAR(300) NOT NULL, fee_desc VARCHAR(500) NOT NULL, description MEDIUMTEXT NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS conversation (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, title VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS chat_message (id VARCHAR(36) PRIMARY KEY, conversation_id VARCHAR(36) NOT NULL, role VARCHAR(16) NOT NULL, content MEDIUMTEXT NOT NULL, extra MEDIUMTEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_document (id VARCHAR(80) PRIMARY KEY, campsite_id VARCHAR(36) NOT NULL, title VARCHAR(200) NOT NULL, category VARCHAR(80) NOT NULL, visibility VARCHAR(16) NOT NULL, current_version VARCHAR(36));
CREATE TABLE IF NOT EXISTS knowledge_version (id VARCHAR(36) PRIMARY KEY, document_id VARCHAR(80) NOT NULL, filename VARCHAR(250) NOT NULL, file_path VARCHAR(500) NOT NULL, content_hash VARCHAR(64) NOT NULL, extracted_text MEDIUMTEXT NOT NULL, status VARCHAR(24) NOT NULL, error_message VARCHAR(300) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_chunk (id VARCHAR(36) PRIMARY KEY, version_id VARCHAR(36) NOT NULL, location VARCHAR(100) NOT NULL, content MEDIUMTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_draft (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, conversation_id VARCHAR(36) NOT NULL, campsite_id VARCHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, title VARCHAR(120) NOT NULL, description MEDIUMTEXT NOT NULL, status VARCHAR(16) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS service_ticket (id VARCHAR(36) PRIMARY KEY, draft_id VARCHAR(36) UNIQUE NOT NULL, user_id VARCHAR(36) NOT NULL, campsite_id VARCHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, title VARCHAR(120) NOT NULL, description MEDIUMTEXT NOT NULL, status VARCHAR(16) NOT NULL, revision INT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_event (id VARCHAR(36) PRIMARY KEY, ticket_id VARCHAR(36) NOT NULL, handler_id VARCHAR(36) NOT NULL, status VARCHAR(16) NOT NULL, reply MEDIUMTEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS agent_run (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, mode VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, elapsed_ms BIGINT NOT NULL, tool_count INT NOT NULL, created_at VARCHAR(40) NOT NULL);



CREATE TABLE IF NOT EXISTS map_quota (bucket VARCHAR(180) PRIMARY KEY, used INT NOT NULL);
